SELECT id, symbol, interval_code, generated_at, decision, original_decision, total_score, market_regime, final_entry_allowed, primary_blocking_stage, strategy_entry_allowed, liquidity_status, liquidity_entry_allowed, entry_authority, entry_authority_max_position_percent, LEFT(liquidity_explanation, 300) AS liq_300 FROM crypto_ai.trade_signal WHERE id IN (163125,165311,165437,165942,170026,171559,156723,159408,165412,167668,171589,176710) ORDER BY id;